/* The propagation rule, extracted pure so it can be tested without mounting the app. The component's
   handler is a thin wrapper: it looks up the cycle's adapt flag and hands the blocks to this. */
/* The back-stack rule, pure so the loop this replaced can be reproduced in a test rather than
   described in a comment. TAB_VIEWS are the bottom-bar destinations: arriving at one is a fresh
   start, so the stack empties. */
const NAV_TABS = ["home", "progress", "profile", "settings"];
function navPush(stack, origin, next) {
    if (NAV_TABS.includes(next))
        return [];
    const i = stack.indexOf(origin);
    const base = i > -1 ? stack.slice(0, i) : stack; // returning to a screen unwinds to it, never stacks on it
    return [...base, origin];
}
function navPop(stack) {
    const st = [...stack];
    const to = st.pop();
    return { stack: st, view: to || "home" }; // an empty stack always lands home, never nowhere
}

