    const hl = elite ? (C.warn || "#F0B429") : (C.accent || "#2563EB");
    ctx.fillStyle = C.bg || "#070A0F";
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = C.card || "#11161F";
