        np.createdAt = Date.now();
        np.name = program.name;
        np.seed = program.seed;
        np.engineV = np.engineV || program.engineV || ENGINE_V;
        np.folder = program.folder;
        np.description = program.description;
        np.cycleId = program.cycleId;
        np.cycleIndex = program.cycleIndex;
        np.blockLabel = program.blockLabel;
